def normalize_existing_phones(apps, schema_editor):
    profile_model = apps.get_model("accounts", "CustomerProfile")
    persian_digits = "۰۱۲۳۴۵۶۷۸۹"
    arabic_digits = "٠١٢٣٤٥٦٧٨٩"
    translation = str.maketrans(
        persian_digits + arabic_digits,
        "0123456789" * 2,
    )

    for profile in profile_model.objects.exclude(phone="").iterator():
        digits = "".join(
            character
            for character in profile.phone.translate(translation)
            if character.isdigit()
        )
        if digits.startswith("0098"):
            digits = f"0{digits[4:]}"
        elif digits.startswith("98") and len(digits) == 12:
            digits = f"0{digits[2:]}"
        profile_model.objects.filter(pk=profile.pk).update(phone=digits)


